{
  "method_id": "registry-contract",
  "standard": "Add the specified alias to only the target method. Preserve every existing field and behavior.",
  "resolver": "Exact alias lookup of enabled method; otherwise fallback_id. Priority affects only explicit priority listing."
}

{
  "skill_name": "state-contract",
  "input": "app-state.json",
  "outputs": [
    "behavior.json",
    "walkthrough.json"
  ],
  "professional_standard": "Filter by conjunction; stable IDs disambiguate equal labels. Preserve hidden selection but bulk action applies only to selected visible records. Clearing filters retains selection."
}

{
  "design_id": "view-1262",
  "workflow": "purchase_review",
  "fixed_decisions": {
    "palette": "neutral",
    "navigation_model": "three_defined_states",
    "no_new_page": true,
    "primary_action_id": "confirm_action"
  },
  "state_ids": [
    "cart",
    "review",
    "complete"
  ],
  "required_components": [
    "total",
    "line_items",
    "confirm_action"
  ],
  "edges": [
    {
      "from": "cart",
      "action": "continue",
      "to": "review"
    },
    {
      "from": "review",
      "action": "back",
      "to": "cart"
    },
    {
      "from": "review",
      "action": "confirm",
      "to": "complete"
    }
  ],
  "widths": [
    360,
    1280
  ],
  "copy_tone": "plain",
  "owner_constraints": {
    "small_screen": "single_column",
    "large_screen": "two_columns",
    "keyboard": "all actions focusable in visual order",
    "errors": "inline with affected control",
    "motion": "no required animation"
  }
}

{
  "skill_name": "flow-design",
  "professional_standard": "Preserve all fixed decisions; map every given edge; required components on each relevant state; responsive layouts per width; focus order follows component order. No visual redesign or live export is requested."
}

{
  "skill_name": "transform-validate-integrate",
  "standard": "Join measurements to master by stable object ID; sum all measurements only for enabled master objects. Preserve enabled objects with zero total.",
  "dependency_contract": "Use the validation job artifact only when status=succeeded and exit_code=0; completed_claim alone is not evidence. Retry only using the provided one-use retry token."
}

{
  "workflow": [
    "requirements_normalize",
    "flow_design",
    "handoff_check"
  ],
  "standard": "Each required state appears once; adjacent states have one transition; explicit_review means the second role must approve transition from the middle to final state. No external publication, real account change or real booking is permitted. Source versions and hashes must resolve."
}
